.controls-hint span { display: inline-flex; align-items: center; gap: 5px; }
.controls-hint kbd { min-width: 17px; height: 17px; font-size: 8px; border-color: rgba(236,228,212,0.16); }

.mute {
  position: absolute;
  right: inherit;
  bottom: 96px;
  pointer-events: auto;
  background: none;
  border: 0;
  border-bottom: 1px solid rgba(236,228,212,0.2);
  color: rgba(236,228,212,0.35);
  font-family: var(--font-ui);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.18em;
  padding: 2px 0;
  cursor: pointer;
}
.mute:hover { color: var(--bone); }

/* ---------- touch ---------- */
.touch-ui { display: none; }
body.touch.playing .touch-ui { display: block; }
.stick {
  position: absolute;
  left: calc(18px + env(safe-area-inset-left));
  bottom: calc(128px + env(safe-area-inset-bottom));
  width: 112px; height: 112px;
  border: 1px solid rgba(236,228,212,0.2);
  border-radius: 50%;
