  font-size: 18px;
  letter-spacing: 0.04em;
}
.tbtn-attack span { font-family: var(--font-ui); font-size: 8px; }
.tbtn-small { width: 56px; height: 56px; }
.touch-actions { grid-template-columns: 56px 56px; align-items: end; }
.touch-actions .tbtn-attack { grid-column: 2; grid-row: 2; justify-self: end; }

/* ---------- start / death ---------- */
.start, .death {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: grid;
  place-items: center;
  padding: 24px;
