}
.start-specs div { display: flex; flex-direction: column; gap: 3px; }
.start-specs b { font-family: var(--font-display); font-weight: 400; font-size: 30px; line-height: 1; color: var(--bone); }
.start-specs span { font-size: 8px; letter-spacing: 0.24em; color: rgba(236,228,212,0.42); font-weight: 700; }
.start-btn {
  pointer-events: auto;
  font-family: var(--font-display);
  font-size: 26px;
  letter-spacing: 0.1em;
  color: #120506;
  background: var(--bone);
  border: 0;
  padding: 13px 54px 11px;
  cursor: pointer;
  clip-path: polygon(10px 0, 100% 0, calc(100% - 10px) 100%, 0 100%);
