  box-shadow: 0 0 0 rgba(224,37,37,0);
}
.start-btn:hover { background: #fff8ea; transform: translateY(-2px); box-shadow: 0 8px 34px rgba(224,37,37,0.35); }
.start-btn:active { transform: translateY(0); }
.start-controls {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 9px 16px;
  margin-top: 24px;
  font-size: 9px;
  letter-spacing: 0.12em;
  color: rgba(236,228,212,0.44);
  font-weight: 700;
}
.start-controls span { display: inline-flex; align-items: center; gap: 5px; }
.start-controls kbd { height: 18px; font-size: 8px; }
.start-note {
  margin-top: 22px;
  font-size: 8px;
  letter-spacing: 0.22em;
  color: rgba(236,228,212,0.26);
  font-weight: 700;
}

.death { background: radial-gradient(ellipse at 50% 45%, rgba(70,4,8,0.5), rgba(4,4,6,0.94) 62%, #050506 100%); }
.death-inner { text-align: center; animation: startIn 0.5s ease both; }
.death h2 {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(64px, 12vw, 130px);
  line-height: 0.9;
  margin: 0;
  color: var(--blood);
  text-shadow: 0 4px 0 #1a0608;
}
#death-stats { font-size: 10px; letter-spacing: 0.24em; color: rgba(236,228,212,0.5); margin: 16px 0 26px; font-weight: 700; }

/* ---------- responsive ---------- */
@media (max-width: 860px) {
  .brand-mark { font-size: 24px; }
  .brand-sub { display: none; }
  .vitals { width: 200px; bottom: 84px; }
  .weapon-card { min-width: 164px; }
  .weapon-icon { width: 32px; height: 32px; }
  .weapon-icon svg { width: 30px; height: 30px; }
  .weapon-name { font-size: 17px; }
  .controls-hint { display: none; }
  .prompt { bottom: 110px; }
  .score-row b { font-size: 24px; }
  .score-row + .score-row b { font-size: 18px; }
  .mute { bottom: 78px; }
}

@media (max-width: 560px) {
  .hud { padding: calc(12px + env(safe-area-inset-top)) calc(12px + env(safe-area-inset-right)) calc(10px + env(safe-area-inset-bottom)) calc(12px + env(safe-area-inset-left)); }
  .brand-mark { font-size: 21px; }
  .score-row b { font-size: 21px; }
  .score-row + .score-row b { font-size: 16px; }
  .vitals { width: 168px; bottom: 70px; padding: 8px 9px 7px; }
  #hp-number { font-size: 21px; }
  .vitals-foot { font-size: 7px; }
  .weapon-card { bottom: 16px; padding: 7px 9px 7px 8px; min-width: 142px; gap: 7px; }
  .weapon-name { font-size: 15px; }
  .weapon-stats { font-size: 7px; }
  .prompt { bottom: 92px; font-size: 10px; }
  .mute { display: none; }
  .start-specs { gap: 18px; margin: 18px 0 20px; }
  .start-specs b { font-size: 24px; }
  .start-copy { font-size: 12px; }
  .start-btn { font-size: 23px; padding: 12px 42px 10px; }
  .start-controls { display: none; }
  .start-note { font-size: 7px; }
  .start-kicker { font-size: 8px; letter-spacing: 0.26em; }
  .feed { display: none; }
}

@media (pointer: coarse) {
  .controls-hint { display: none; }
  .prompt { bottom: 250px; }
}

