// Tiny procedural sound kit — no external audio assets.
export class Sound {
  constructor() {
    this.ctx = null;
    this.out = null;
    this.noiseBuf = null;
    this.muted = false;
    this.ambience = null;
  }

  unlock() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    const ctx = new Ctx();
    this.ctx = ctx;

    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 22;
    comp.ratio.value = 8;
    comp.attack.value = 0.003;
    comp.release.value = 0.22;

    const out = ctx.createGain();
    out.gain.value = this.muted ? 0 : 0.5;
    comp.connect(out).connect(ctx.destination);
    this.out = out;

    const len = Math.floor(ctx.sampleRate * 1.2);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = 0.94 * last + 0.06 * white;
      data[i] = last * 3.2;
    }
    this.noiseBuf = buf;
    this.startAmbience();
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.out && this.ctx) {
      this.out.gain.cancelScheduledValues(this.ctx.currentTime);
      this.out.gain.setTargetAtTime(muted ? 0 : 0.5, this.ctx.currentTime, 0.05);
    }
  }

  startAmbience() {
    if (!this.ctx || this.ambience) return;
    const ctx = this.ctx;
    const g = ctx.createGain();
    g.gain.value = 0;
    g.gain.setTargetAtTime(0.035, ctx.currentTime, 1.8);
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 180;
    filter.Q.value = 3;

    const a = ctx.createOscillator();
    const b = ctx.createOscillator();
    a.type = 'sawtooth';
    b.type = 'sawtooth';
    a.frequency.value = 41;
    b.frequency.value = 41.7;
    a.connect(filter);
    b.connect(filter);
    filter.connect(g).connect(this.out);
    a.start();
    b.start();

    const lfo = ctx.createOscillator();
    const lfoGain = ctx.createGain();
    lfo.frequency.value = 0.09;
    lfoGain.gain.value = 0.014;
    lfo.connect(lfoGain).connect(g.gain);
    lfo.start();

    this.ambience = { a, b, lfo, g };
  }

  _now(delay = 0) { return this.ctx.currentTime + delay; }

  tone(freq, dur, { type = 'sine', gain = 0.2, end = freq, delay = 0, attack = 0.004 } = {}) {
    if (!this.ctx) return;
    const t = this._now(delay);
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(Math.max(20, freq), t);
    o.frequency.exponentialRampToValueAtTime(Math.max(20, end), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(this.out);
    o.start(t);
    o.stop(t + dur + 0.03);
  }

  noise(dur, { gain = 0.2, freq = 900, end = 300, q = 0.8, delay = 0, type = 'lowpass' } = {}) {
    if (!this.ctx || !this.noiseBuf) return;
    const t = this._now(delay);
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    src.playbackRate.value = 1 + Math.random() * 0.2;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.Q.value = q;
    filter.frequency.setValueAtTime(Math.max(40, freq), t);
    filter.frequency.exponentialRampToValueAtTime(Math.max(40, end), t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter).connect(g).connect(this.out);
    src.start(t, Math.random() * 0.2);
    src.stop(t + dur + 0.02);
  }

  punch() {
    this.noise(0.09, { gain: 0.24, freq: 620, end: 130, q: 1.2 });
    this.tone(120, 0.1, { type: 'triangle', gain: 0.22, end: 46 });
  }

  swing() {
    this.noise(0.16, { gain: 0.14, freq: 2400, end: 380, q: 1.6, type: 'bandpass' });
  }

  hit() {
    this.noise(0.12, { gain: 0.32, freq: 1200, end: 160, q: 1.1 });
    this.tone(150, 0.14, { type: 'square', gain: 0.12, end: 48 });
  }

  crit() {
    this.noise(0.2, { gain: 0.36, freq: 2200, end: 220, q: 0.9 });
    this.tone(210, 0.2, { type: 'sawtooth', gain: 0.12, end: 42 });
  }

  gib() {
    this.noise(0.42, { gain: 0.4, freq: 1000, end: 90, q: 0.7 });
    this.tone(72, 0.45, { type: 'sawtooth', gain: 0.16, end: 30 });
    this.tone(190, 0.18, { type: 'triangle', gain: 0.1, end: 60, delay: 0.04 });
  }

  hurt() {
    this.tone(95, 0.22, { type: 'sawtooth', gain: 0.2, end: 40 });
    this.noise(0.18, { gain: 0.22, freq: 500, end: 110 });
  }

  grab() {
    this.noise(0.13, { gain: 0.18, freq: 500, end: 1400, q: 2, type: 'bandpass' });
    this.tone(260, 0.09, { type: 'triangle', gain: 0.1, end: 340 });
  }

  pickup() {
    this.tone(420, 0.08, { type: 'triangle', gain: 0.14, end: 620 });
    this.tone(640, 0.1, { type: 'triangle', gain: 0.1, end: 880, delay: 0.05 });
  }

  throw() {
    this.noise(0.22, { gain: 0.16, freq: 700, end: 2400, q: 1.4, type: 'bandpass' });
    this.tone(180, 0.18, { type: 'triangle', gain: 0.1, end: 90 });
  }

  spawn() {
    this.tone(48, 0.7, { type: 'sawtooth', gain: 0.2, end: 24 });
    this.noise(0.6, { gain: 0.22, freq: 240, end: 1800, q: 1.4, type: 'bandpass' });
    this.tone(320, 0.3, { type: 'triangle', gain: 0.08, end: 120, delay: 0.08 });
  }

  step() {
    this.noise(0.07, { gain: 0.05, freq: 220, end: 90 });
  }

  ui() {
    this.tone(540, 0.06, { type: 'triangle', gain: 0.09, end: 720 });
  }

  death() {
    this.tone(70, 1.1, { type: 'sawtooth', gain: 0.24, end: 26 });
    this.noise(0.9, { gain: 0.2, freq: 900, end: 60 });
  }
}

import * as THREE from 'three';

const _v = new THREE.Vector3();
const _q = new THREE.Quaternion();

function rand(a, b) { return a + Math.random() * (b - a); }

// Pooled blood, gibs, decals and impact rings. All procedural geometry.
export class FX {
  constructor(scene) {
    this.scene = scene;
    this.particles = [];
    this.chunks = [];
    this.decals = [];
    this.rings = [];
    this.slashes = [];

    this.dropGeo = new THREE.IcosahedronGeometry(0.035, 0);
    this.chunkGeo = new THREE.BoxGeometry(1, 1, 1);
    this.decalGeo = new THREE.CircleGeometry(1, 14);
    this.ringGeo = new THREE.RingGeometry(0.72, 1, 40);

    this.matBlood = new THREE.MeshStandardMaterial({ color: 0x7c1014, roughness: 0.42, metalness: 0.05 });
    this.matBloodDark = new THREE.MeshStandardMaterial({ color: 0x4d090c, roughness: 0.55 });
    this.matBone = new THREE.MeshStandardMaterial({ color: 0xd9cfb8, roughness: 0.7 });
    this.matFlesh = new THREE.MeshStandardMaterial({ color: 0x9c5347, roughness: 0.62 });
    this.matDecal = new THREE.MeshBasicMaterial({ color: 0x3f0709, transparent: true, opacity: 0.78, depthWrite: false });

    this.maxDecals = 64;
    this.decalIndex = 0;

    this.dust = this.makeDust();
    scene.add(this.dust);
  }

  makeDust() {
    const count = 140;
    const positions = new Float32Array(count * 3);
    const seeds = new Float32Array(count);
    for (let i = 0; i < count; i++) {
      positions[i * 3] = rand(-6, 6);
      positions[i * 3 + 1] = rand(0.1, 5);
      positions[i * 3 + 2] = rand(-6, 6);
      seeds[i] = rand(0, Math.PI * 2);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      color: 0xc9b9a3, size: 0.018, transparent: true, opacity: 0.36,
      depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true
    });
    const points = new THREE.Points(geo, mat);
    points.userData.seeds = seeds;
    return points;
  }

  spawnDrop(pos, dir, opts = {}) {
    const { count = 12, power = 1, color = 'blood', up = 0.6, spread = 1.3, size = 1 } = opts;
    for (let i = 0; i < count; i++) {
      let p = this.particles.find(x => !x.active);
      if (!p) {
        const mesh = new THREE.Mesh(this.dropGeo, this.matBlood);
        mesh.castShadow = false;
        this.scene.add(mesh);
        p = { mesh, active: false, vel: new THREE.Vector3(), spin: new THREE.Vector3(), life: 0, max: 1, gravity: 16 };
        this.particles.push(p);
      }
      p.active = true;
      p.mesh.visible = true;
      p.mesh.material = color === 'bone' ? this.matBone : color === 'flesh' ? this.matFlesh : (Math.random() < 0.35 ? this.matBloodDark : this.matBlood);
      p.mesh.position.copy(pos);
      p.mesh.position.x += rand(-0.08, 0.08);
      p.mesh.position.y += rand(-0.05, 0.12);
      p.mesh.position.z += rand(-0.08, 0.08);
      p.mesh.scale.setScalar(rand(0.5, 1.5) * size);
      p.vel.set(
        dir.x * power * rand(0.5, 1.4) + rand(-spread, spread),
        rand(0.3, 1.1) * up * power + rand(0, 0.5),
        dir.z * power * rand(0.5, 1.4) + rand(-spread, spread)
      );
      p.spin.set(rand(-12, 12), rand(-12, 12), rand(-12, 12));
      p.life = 0;
      p.max = rand(0.5, 1.1);
      p.gravity = rand(13, 20);
    }
  }

  bloodBurst(pos, dir, count = 14, power = 1) {
    this.spawnDrop(pos, dir, { count, power, up: 1, spread: 1.1 });
  }

  spark(pos, dir) {
    this.spawnDrop(pos, dir, { count: 5, power: 0.5, color: 'bone', up: 0.7, spread: 0.9, size: 0.7 });
  }

  chunks(pos, count = 8) {
    for (let i = 0; i < count; i++) {
      let c = this.chunks.find(x => !x.active);
      if (!c) {
        const mesh = new THREE.Mesh(this.chunkGeo, this.matFlesh);
        mesh.castShadow = true;
        this.scene.add(mesh);
        c = { mesh, active: false, vel: new THREE.Vector3(), spin: new THREE.Vector3(), life: 0, max: 1 };
        this.chunks.push(c);
      }
      c.active = true;
      c.mesh.visible = true;
      c.mesh.material = Math.random() < 0.3 ? this.matBone : Math.random() < 0.5 ? this.matBloodDark : this.matFlesh;
      c.mesh.position.copy(pos);
      c.mesh.position.y += rand(0.2, 0.9);
      c.mesh.scale.set(rand(0.04, 0.14), rand(0.03, 0.1), rand(0.04, 0.12));
      c.vel.set(rand(-2.6, 2.6), rand(1.5, 4.6), rand(-2.6, 2.6));
      c.spin.set(rand(-14, 14), rand(-14, 14), rand(-14, 14));
      c.life = 0;
      c.max = rand(2.2, 4);
      c.mesh.rotation.set(rand(0, 6), rand(0, 6), rand(0, 6));
    }
  }

  bloodPool(pos, size = 0.5) {
    const patches = 3 + Math.floor(Math.random() * 4);
    for (let i = 0; i < patches; i++) {
      let d = this.decals.find(x => !x.active);
      if (!d) {
        if (this.decals.length >= this.maxDecals) d = this.decals[this.decalIndex++ % this.maxDecals];
        else {
          const mesh = new THREE.Mesh(this.decalGeo, this.matDecal.clone());
          mesh.rotation.x = -Math.PI / 2;
          mesh.renderOrder = 1;
          this.scene.add(mesh);
          d = { mesh, active: false, life: 0, max: 999 };
          this.decals.push(d);
        }
      }
      d.active = true;
      d.mesh.visible = true;
      d.mesh.position.set(pos.x + rand(-size * 0.55, size * 0.55), 0.012 + Math.random() * 0.002, pos.z + rand(-size * 0.55, size * 0.55));
      const s = rand(0.12, 0.42) * size * 2.2;
      d.mesh.scale.set(s * rand(0.7, 1.6), s, 1);
      d.mesh.rotation.z = rand(0, Math.PI * 2);
      d.mesh.material.opacity = rand(0.5, 0.85);
      d.life = 0;
      d.max = 999;
    }
  }

  ring(pos, color = 0xff3326, size = 0.55, dur = 0.5) {
    let r = this.rings.find(x => !x.active);
    if (!r) {
      const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
      const mesh = new THREE.Mesh(this.ringGeo, mat);
      mesh.rotation.x = -Math.PI / 2;
      mesh.renderOrder = 2;
      this.scene.add(mesh);
      r = { mesh, active: false, life: 0, max: dur, size };
      this.rings.push(r);
    }
    r.active = true;
    r.mesh.visible = true;
    r.mesh.position.copy(pos);
    r.mesh.position.y = Math.max(0.02, pos.y);
    r.mesh.material.color.setHex(color);
    r.mesh.material.opacity = 0.9;
    r.mesh.scale.setScalar(size);
    r.life = 0;
    r.max = dur;
    r.size = size;
  }

  slash(pos, yaw, color = 0xcfe6ff) {
    let s = this.slashes.find(x => !x.active);
    if (!s) {
      const geo = new THREE.TorusGeometry(0.62, 0.022, 4, 28, Math.PI * 1.15);
      const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.7, depthWrite: false, blending: THREE.AdditiveBlending });
      const mesh = new THREE.Mesh(geo, mat);
      this.scene.add(mesh);
      s = { mesh, active: false, life: 0, max: 0.2 };
      this.slashes.push(s);
    }
    s.active = true;
    s.mesh.visible = true;
    s.mesh.position.copy(pos);
    s.mesh.position.y = 1.05;
    s.mesh.rotation.set(Math.PI / 2, 0, 0);
    s.mesh.rotation.z = -yaw + Math.PI * 0.5;
    s.mesh.material.color.setHex(color);
    s.mesh.material.opacity = 0.8;
    s.mesh.scale.setScalar(0.85);
    s.life = 0;
    s.max = 0.2;
  }

  update(dt, time) {
    // particles
    for (const p of this.particles) {
      if (!p.active) continue;
      p.life += dt;
      if (p.life >= p.max) { p.active = false; p.mesh.visible = false; continue; }
      p.vel.y -= p.gravity * dt;
      p.mesh.position.addScaledVector(p.vel, dt);
      if (p.mesh.position.y < 0.03) {
        p.mesh.position.y = 0.03;
        p.vel.y *= -0.25;
        p.vel.x *= 0.55;
        p.vel.z *= 0.55;
      }
      p.mesh.rotation.x += p.spin.x * dt;
      p.mesh.rotation.y += p.spin.y * dt;
      const t = p.life / p.max;
      p.mesh.scale.multiplyScalar(1 - dt * 0.35);
      if (t > 0.72) p.mesh.visible = Math.random() > 0.4;
    }

    // chunks
    for (const c of this.chunks) {
      if (!c.active) continue;
      c.life += dt;
      if (c.life >= c.max) { c.active = false; c.mesh.visible = false; continue; }
      c.vel.y -= 15 * dt;
      c.mesh.position.addScaledVector(c.vel, dt);
      if (c.mesh.position.y < 0.05) {
        c.mesh.position.y = 0.05;
        c.vel.y *= -0.32;
        c.vel.x *= 0.7;
        c.vel.z *= 0.7;
        c.spin.multiplyScalar(0.7);
      }
      c.mesh.rotation.x += c.spin.x * dt;
      c.mesh.rotation.y += c.spin.y * dt;
      c.mesh.rotation.z += c.spin.z * dt;
      if (c.life > c.max - 0.6) {
        c.mesh.scale.multiplyScalar(1 - dt * 2.5);
      }
    }

    // rings
    for (const r of this.rings) {
      if (!r.active) continue;
      r.life += dt;
      if (r.life >= r.max) { r.active = false; r.mesh.visible = false; continue; }
      const t = r.life / r.max;
      r.mesh.scale.setScalar(r.size * (0.35 + t * 1.5));
      r.mesh.material.opacity = (1 - t) * 0.9;
    }

    // slashes
    for (const s of this.slashes) {
      if (!s.active) continue;
      s.life += dt;
      if (s.life >= s.max) { s.active = false; s.mesh.visible = false; continue; }
      const t = s.life / s.max;
      s.mesh.material.opacity = (1 - t) * 0.8;
      s.mesh.scale.setScalar(0.85 + t * 0.35);
    }

    // dust
    const pos = this.dust.geometry.attributes.position;
    const seeds = this.dust.userData.seeds;
    for (let i = 0; i < pos.count; i++) {
      let y = pos.getY(i) + Math.sin(time * 0.25 + seeds[i]) * dt * 0.06;
      let x = pos.getX(i) + Math.cos(time * 0.18 + seeds[i] * 1.7) * dt * 0.04;
      if (y > 5) y = 0.1;
      pos.setY(i, y);
      pos.setX(i, x);
    }
    pos.needsUpdate = true;
  }

  clear() {
    for (const p of this.particles) { p.active = false; p.mesh.visible = false; }
    for (const c of this.chunks) { c.active = false; c.mesh.visible = false; }
    for (const d of this.decals) { d.active = false; d.mesh.visible = false; }
    for (const r of this.rings) { r.active = false; r.mesh.visible = false; }
    for (const s of this.slashes) { s.active = false; s.mesh.visible = false; }
  }
}

import * as THREE from 'three';

export const WEAPON_DEFS = {
  fist: {
    name: 'FISTS', damage: 11, range: 0.92, cooldown: 0.34, knockback: 1.5, speed: 'FAST', arc: 1.5,
    throwDamage: 0
  },
  pickaxe: {
    name: 'PICKAXE', damage: 32, range: 1.18, cooldown: 0.66, knockback: 3.4, speed: 'HEAVY', arc: 1.25,
    throwDamage: 42
  },
  hatchet: {
    name: 'HATCHET', damage: 20, range: 1.02, cooldown: 0.4, knockback: 2.1, speed: 'QUICK', arc: 1.45,
    throwDamage: 30
  }
};

const steel = new THREE.MeshStandardMaterial({ color: 0x9aa6ae, roughness: 0.34, metalness: 0.85 });
const steelDark = new THREE.MeshStandardMaterial({ color: 0x59636b, roughness: 0.45, metalness: 0.8 });
const edgeMat = new THREE.MeshStandardMaterial({ color: 0xd6e6ef, roughness: 0.2, metalness: 0.95, emissive: 0x2a3d48, emissiveIntensity: 0.6 });
const wood = new THREE.MeshStandardMaterial({ color: 0x6f4728, roughness: 0.82, metalness: 0.02 });
const woodDark = new THREE.MeshStandardMaterial({ color: 0x4a2d18, roughness: 0.85 });
const wrap = new THREE.MeshStandardMaterial({ color: 0x211a17, roughness: 0.95 });
const accent = new THREE.MeshStandardMaterial({ color: 0x9c1b1b, roughness: 0.7 });

function handle(length, radius, bandCount, bandYs) {
  const g = new THREE.Group();
  const h = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.82, radius, length, 8), wood);
  h.position.y = length / 2 - 0.18;
  h.castShadow = true;
  g.add(h);
  for (let i = 0; i < bandCount; i++) {
    const band = new THREE.Mesh(new THREE.CylinderGeometry(radius * 1.12, radius * 1.12, 0.026, 8), i === 0 ? accent : wrap);
    band.position.y = bandYs[i];
    band.castShadow = true;
    g.add(band);
  }
  return g;
}

function buildHatchet() {
  const g = new THREE.Group();
  g.add(handle(0.56, 0.031, 3, [-0.08, 0.0, 0.08]));

  const head = new THREE.Group();
  head.position.set(0, 0.4, 0);
  g.add(head);

  const shape = new THREE.Shape();
  shape.moveTo(-0.015, -0.075);
  shape.lineTo(0.105, -0.095);
  shape.lineTo(0.205, -0.045);
  shape.lineTo(0.235, 0.045);
  shape.lineTo(0.155, 0.11);
  shape.lineTo(0.02, 0.09);
  shape.lineTo(-0.015, 0.045);
  shape.closePath();
  const bladeGeo = new THREE.ExtrudeGeometry(shape, { depth: 0.055, bevelEnabled: true, bevelSize: 0.006, bevelThickness: 0.005, bevelSegments: 1, steps: 1 });
  bladeGeo.translate(0, 0, -0.0275);
  const blade = new THREE.Mesh(bladeGeo, steel);
  blade.castShadow = true;
  head.add(blade);

  const edge = new THREE.Mesh(new THREE.BoxGeometry(0.016, 0.16, 0.062), edgeMat);
  edge.position.set(0.222, 0.005, 0);
  edge.rotation.z = -0.2;
  edge.castShadow = true;
  head.add(edge);

  const poll = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.1, 0.075), steelDark);
  poll.position.set(-0.04, 0.0, 0);
  poll.castShadow = true;
  head.add(poll);

  const eye = new THREE.Mesh(new THREE.CylinderGeometry(0.036, 0.036, 0.075, 8), steelDark);
  eye.rotation.x = Math.PI / 2;
  eye.position.set(0.0, 0.0, 0);
  head.add(eye);

  return g;
}

function buildPickaxe() {
  const g = new THREE.Group();
  g.add(handle(0.8, 0.036, 3, [-0.11, 0.02, 0.15]));

  const head = new THREE.Group();
  head.position.set(0, 0.6, 0);
  g.add(head);

  const center = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.13, 0.1), steelDark);
  center.castShadow = true;
  head.add(center);

  for (const side of [-1, 1]) {
    const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.032, 0.3, 4), steel);
    arm.rotation.z = Math.PI / 2;
    arm.rotation.y = Math.PI / 4;
    arm.rotation.x = side * -0.18;
    arm.position.set(side * 0.2, side * -0.03, 0);
    arm.castShadow = true;
    head.add(arm);

    const tip = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.04, 0.22, 4), steel);
    tip.rotation.z = Math.PI / 2;
    tip.rotation.y = Math.PI / 4;
    tip.rotation.x = side * -0.32;
    tip.position.set(side * 0.42, side * -0.08, 0);
    tip.castShadow = true;
    head.add(tip);

    const glint = new THREE.Mesh(new THREE.BoxGeometry(0.19, 0.008, 0.03), edgeMat);
    glint.position.set(side * 0.4, side * -0.085, 0);
    glint.rotation.z = side * -0.32;
    head.add(glint);
  }

  return g;
}

export function buildWeaponMesh(kind) {
  return kind === 'pickaxe' ? buildPickaxe() : buildHatchet();
}

const ringGeo = new THREE.RingGeometry(0.34, 0.44, 32);
const ringMat = new THREE.MeshBasicMaterial({ color: 0xffa347, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });

export class WeaponDrop {
  constructor(kind, scene, fx, x, z) {
    this.kind = kind;
    this.def = WEAPON_DEFS[kind];
    this.scene = scene;
    this.fx = fx;
    this.group = buildWeaponMesh(kind);
    this.group.position.set(x, 0.185, z);
    this.group.rotation.y = Math.random() * Math.PI * 2;
    this.group.traverse(o => { if (o.isMesh) o.castShadow = true; });

    this.ring = new THREE.Mesh(ringGeo, ringMat.clone());
    this.ring.rotation.x = -Math.PI / 2;
    this.ring.position.y = -0.17;
    this.ring.visible = true;
    this.group.add(this.ring);

    this.state = 'ground';
    this.vel = new THREE.Vector3();
    this.spin = new THREE.Vector3();
    this.hitCooldown = 0;
    this.baseY = 0.185;
    this.idle = Math.random() * 10;
    scene.add(this.group);
  }

  get worldPosition() {
    return this.group.getWorldPosition(new THREE.Vector3());
  }

  attach(anchor) {
    this.state = 'held';
    this.ring.visible = false;
    this.group.rotation.set(0, 0, 0);
    this.group.position.set(0.02, 0, 0.04);
    anchor.add(this.group);
  }

  dropToGround(pos, yaw = 0) {
    this.state = 'ground';
    this.scene.attach(this.group);
    this.group.position.copy(pos);
    this.group.position.y = this.baseY;
    this.group.rotation.set(0, yaw, 0);
    this.ring.visible = true;
    this.hitCooldown = 0;
    this.fx.ring(this.group.position, 0xffa347, 0.32, 0.35);
  }

  throwFrom(pos, dir) {
    this.state = 'thrown';
    this.ring.visible = false;
    this.scene.attach(this.group);
    this.group.position.copy(pos);
    this.group.rotation.set(Math.random() * 2, Math.random() * 2, Math.random() * 2);
    this.vel.set(dir.x * 8.2, 3.4, dir.z * 8.2);
    this.spin.set(rand(-10, 10), rand(-10, 10), rand(-10, 10));
    this.hitCooldown = 0.08;
  }

  update(dt, time, game) {
    this.hitCooldown = Math.max(0, this.hitCooldown - dt);
    if (this.state === 'ground') {
      this.idle += dt;
      this.group.position.y = this.baseY + Math.sin(this.idle * 2.2) * 0.012;
      this.group.rotation.y += dt * 0.55;
      this.ring.material.opacity = 0.38 + Math.sin(this.idle * 2.6) * 0.16;
      this.ring.scale.setScalar(1 + Math.sin(this.idle * 2.6) * 0.06);
    } else if (this.state === 'thrown') {
      this.vel.y -= 17 * dt;
      this.group.position.addScaledVector(this.vel, dt);
      this.group.rotation.x += this.spin.x * dt;
      this.group.rotation.y += this.spin.y * dt;
      this.group.rotation.z += this.spin.z * dt;

      const p = this.group.position;
      if (p.y < this.baseY) {
        p.y = this.baseY;
        if (Math.abs(this.vel.y) > 1.2) {
          this.vel.y *= -0.42;
          this.vel.x *= 0.72;
          this.vel.z *= 0.72;
          this.spin.multiplyScalar(0.72);
          if (Math.random() < 0.5) this.fx.bloodBurst(p, new THREE.Vector3(0, 1, 0), 3, 0.4);
        } else {
          this.state = 'ground';
          this.idle = 0;
          this.group.rotation.set(0, this.group.rotation.y, 0);
          this.group.position.y = this.baseY;
          this.ring.visible = true;
          this.fx.ring(p, 0xffa347, 0.35, 0.4);
        }
      }

      // clamp inside the pit (soft bounce)
      if (p.x > 1.9) { p.x = 1.9; this.vel.x *= -0.4; }
      if (p.x < -1.9) { p.x = -1.9; this.vel.x *= -0.4; }
      if (p.z > 1.9) { p.z = 1.9; this.vel.z *= -0.4; }
      if (p.z < -1.9) { p.z = -1.9; this.vel.z *= -0.4; }

      if (this.hitCooldown <= 0 && this.vel.lengthSq() > 5) {
        for (const npc of game.npcs) {
          if (!npc.alive || npc.state === 'grabbed' || npc.state === 'dead') continue;
          const d = npc.group.position.distanceTo(p);
          if (d < 0.48) {
            const dir = this.vel.clone().normalize();
            game.hitNPC(npc, this.def.throwDamage, dir, { weapon: this.kind, thrown: true });
            this.hitCooldown = 0.35;
            this.vel.multiplyScalar(-0.25);
            this.vel.y = 2;
            this.fx.bloodBurst(p, dir, 12, 1.2);
            game.shake(0.16);
            break;
          }
        }
      }
    }
  }
}

function rand(a, b) { return a + Math.random() * (b - a); }

